    int k = fit->second;

    // Get the opposite cell sharing this facet
    RT::Cell_handle nc = c->neighbor(k);

    // Check if this is a finite facet and large enough
    if (!is_large_facet(rt, *fit, threshold)) {
        continue;
    }

    // Get the dual points (weighted points) of the two cells
    Point p1 = c->vertex((k + 1) % 4)->point();
    Point p2 = nc->vertex((k + 1) % 4)->point();

    // Calculate the edge length as the area information
    double length = std::sqrt(CGAL::squared_distance(p1, p2));

    // Add edge to mesh: two vertices connected by an edge
    std::vector<unsigned> edge_vertices = {result.vertices.size(), result.vertices.size() + 1};
    result.vertices.push_back(p1);
    result.vertices.push_back(p2);
    result.push_back(edge_vertices, length);
}
return result;

